--
-- Name: get_mesas_resumen(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_mesas_resumen(p_negocio_id uuid) RETURNS TABLE(mesa_id uuid, numero_mesa integer, nombre_mesa text, zona_id uuid, zona_nombre text, capacidad integer, estado_mesa text, orden_id uuid, estado_orden text, total_orden numeric, hora_apertura timestamp with time zone, items_count bigint, tiempo_minutos integer)
    LANGUAGE plpgsql
    AS $$
BEGIN
  RETURN QUERY
  SELECT
    rt.id,
    rt.numero_mesa,
    rt.nombre_mesa,
    rt.zona_id,
    rz.nombre,
    rt.capacidad,
    rt.estado,
    ro.id,
    ro.estado,
    ro.total,
    ro.hora_apertura,
    COUNT(roi.id),
    EXTRACT(EPOCH FROM (NOW() - ro.hora_apertura))::INT / 60
  FROM restaurant_tables rt
  JOIN restaurant_zones rz ON rz.id = rt.zona_id
  LEFT JOIN restaurant_orders ro
    ON ro.table_id = rt.id
    AND ro.estado NOT IN ('cerrada', 'cancelada')
  LEFT JOIN restaurant_order_items roi
    ON roi.order_id = ro.id
    AND roi.estado != 'cancelado'
  WHERE rt.negocio_id = p_negocio_id
    AND rt.activa = true
  GROUP BY rt.id, rt.numero_mesa, rt.nombre_mesa, rt.zona_id,
           rz.nombre, rt.capacidad, rt.estado,
           ro.id, ro.estado, ro.total, ro.hora_apertura
  ORDER BY rz.nombre, rt.numero_mesa;
END;
$$;


ALTER FUNCTION public.get_mesas_resumen(p_negocio_id uuid) OWNER TO postgres;

--
-- Name: get_ruteo_orden(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_ruteo_orden(p_order_id uuid) RETURNS TABLE(printer_id uuid, printer_nombre text, printer_ip text, printer_puerto integer, printer_tipo text, printer_tipo_conexion text, printer_puerto_usb text, printer_chars integer, printer_corte boolean, printer_copies integer, item_id uuid, menu_item_nombre text, cantidad integer, modificadores jsonb, notas_especiales text, comensal_asignado integer)
    LANGUAGE sql STABLE
    AS $$
  SELECT
    rp.id                   AS printer_id,
    rp.nombre               AS printer_nombre,
    rp.ip                   AS printer_ip,
    rp.puerto               AS printer_puerto,
    rp.tipo                 AS printer_tipo,
    rp.tipo_conexion        AS printer_tipo_conexion,
    rp.puerto_usb           AS printer_puerto_usb,
    rp.caracteres_por_linea AS printer_chars,
    rp.corte_automatico     AS printer_corte,
    rp.copies               AS printer_copies,
    roi.id                  AS item_id,
    mi.nombre               AS menu_item_nombre,
    roi.cantidad,
    roi.modificadores::JSONB,
    roi.notas_especiales,
    roi.comensal_asignado
  FROM restaurant_order_items roi
  JOIN menu_items          mi  ON mi.id  = roi.menu_item_id
  JOIN menu_categories     mc  ON mc.id  = mi.categoria_id
  JOIN restaurant_printers rp  ON rp.id  = mc.printer_id
  WHERE roi.order_id = p_order_id
    AND roi.estado   = 'pendiente'
    AND mc.printer_id IS NOT NULL
  ORDER BY rp.tipo, mi.nombre;
$$;


ALTER FUNCTION public.get_ruteo_orden(p_order_id uuid) OWNER TO postgres;

--
-- Name: obtener_siguiente_ncf(text, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.obtener_siguiente_ncf(tipo_solicitado text, p_negocio_id uuid) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_seq       RECORD;
  v_nuevo_num INT;
  v_ncf       TEXT;
BEGIN
  -- Bloquear la fila para evitar secuencias duplicadas bajo concurrencia
  SELECT *
    INTO v_seq
    FROM secuencias_ncf
   WHERE tipo_ncf    = UPPER(tipo_solicitado)
     AND negocio_id  = p_negocio_id
     AND activo      = TRUE
     AND (fecha_vencimiento IS NULL OR fecha_vencimiento >= CURRENT_DATE)
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'No hay secuencia NCF activa para tipo % en el negocio %',
      tipo_solicitado, p_negocio_id;
  END IF;

  v_nuevo_num := v_seq.numero_actual + 1;

  IF v_nuevo_num > v_seq.rango_final THEN
    RAISE EXCEPTION 'Secuencia NCF % agotada (rango_final = %)',
      tipo_solicitado, v_seq.rango_final;
  END IF;

  -- Actualizar secuencia
  UPDATE secuencias_ncf
     SET numero_actual        = v_nuevo_num,
         ultima_actualizacion = NOW()
   WHERE id = v_seq.id;

  -- Formato: prefijo (B01, B02…) + número 11 dígitos
  v_ncf := UPPER(v_seq.prefijo) || LPAD(v_nuevo_num::TEXT, 11, '0');
  RETURN v_ncf;
END;
$$;


ALTER FUNCTION public.obtener_siguiente_ncf(tipo_solicitado text, p_negocio_id uuid) OWNER TO postgres;

--
-- Name: recalcular_totales_orden(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.recalcular_totales_orden() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_negocio_id    UUID;
  v_tasa          NUMERIC;
  v_modo          VARCHAR(20);
  v_suma_items    NUMERIC;
  v_subtotal      NUMERIC;
  v_impuesto      NUMERIC;
  v_descuento     NUMERIC;
  v_total         NUMERIC;
BEGIN
  -- Obtener el negocio_id de la orden
  SELECT negocio_id INTO v_negocio_id
  FROM restaurant_orders
  WHERE id = COALESCE(NEW.order_id, OLD.order_id);

  -- Leer configuración fiscal del negocio
  SELECT
    COALESCE(tasa_itbis, 0),
    COALESCE(modo_impuesto, 'sin_impuesto')
  INTO v_tasa, v_modo
  FROM negocios
  WHERE id = v_negocio_id;

  -- Suma bruta de items activos (precio_unitario * cantidad)
  SELECT COALESCE(SUM(subtotal), 0) INTO v_suma_items
  FROM restaurant_order_items
  WHERE order_id = COALESCE(NEW.order_id, OLD.order_id)
    AND estado <> 'cancelado';

  -- Descuento de la orden (si existe)
  SELECT COALESCE(descuento, 0) INTO v_descuento
  FROM restaurant_orders
  WHERE id = COALESCE(NEW.order_id, OLD.order_id);

  -- Calcular subtotal e impuesto según modo
  CASE v_modo
    WHEN 'incluido' THEN
      -- El precio ya incluye ITBIS: extraer impuesto hacia atrás
      IF v_tasa > 0 THEN
        v_subtotal  := ROUND((v_suma_items - v_descuento) / (1 + v_tasa), 2);
        v_impuesto  := ROUND((v_suma_items - v_descuento) - v_subtotal, 2);
      ELSE
        v_subtotal  := v_suma_items - v_descuento;
        v_impuesto  := 0;
      END IF;

    WHEN 'encima' THEN
      -- ITBIS se suma por encima del precio base
      v_subtotal  := v_suma_items - v_descuento;
      v_impuesto  := ROUND(v_subtotal * v_tasa, 2);

    ELSE -- 'sin_impuesto'
      v_subtotal  := v_suma_items - v_descuento;
      v_impuesto  := 0;
  END CASE;

  v_total := v_subtotal + v_impuesto;

  -- Actualizar totales en la orden
  UPDATE restaurant_orders
  SET
    subtotal    = v_subtotal,
    impuesto    = v_impuesto,
    total       = v_total,
    updated_at  = NOW()
  WHERE id = COALESCE(NEW.order_id, OLD.order_id);

  RETURN COALESCE(NEW, OLD);
END;
$$;


ALTER FUNCTION public.recalcular_totales_orden() OWNER TO postgres;

--
-- Name: registrar_movimiento_inventario(uuid, uuid, text, numeric, text, uuid, text, bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.registrar_movimiento_inventario(p_negocio_id uuid, p_inventory_item_id uuid, p_tipo text, p_cantidad numeric, p_razon text DEFAULT NULL::text, p_referencia_id uuid DEFAULT NULL::uuid, p_referencia_tipo text DEFAULT NULL::text, p_usuario_id bigint DEFAULT NULL::bigint) RETURNS uuid
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_cantidad_anterior  DECIMAL(10,3);
  v_cantidad_posterior DECIMAL(10,3);
  v_movement_id        UUID;
BEGIN
  SELECT cantidad_actual INTO v_cantidad_anterior
  FROM restaurant_inventory
  WHERE id = p_inventory_item_id AND negocio_id = p_negocio_id
  FOR UPDATE;

  IF v_cantidad_anterior IS NULL THEN
    RAISE EXCEPTION 'Ítem de inventario no encontrado: %', p_inventory_item_id;
  END IF;

  IF p_tipo IN ('entrada', 'ajuste') THEN
    v_cantidad_posterior := v_cantidad_anterior + ABS(p_cantidad);
  ELSIF p_tipo IN ('salida', 'merma', 'produccion') THEN
    v_cantidad_posterior := v_cantidad_anterior - ABS(p_cantidad);
    IF v_cantidad_posterior < 0 THEN
      RAISE EXCEPTION 'Stock insuficiente. Disponible: %, Solicitado: %',
        v_cantidad_anterior, ABS(p_cantidad);
    END IF;
  ELSE
    RAISE EXCEPTION 'Tipo de movimiento inválido: %', p_tipo;
  END IF;

  UPDATE restaurant_inventory
  SET cantidad_actual = v_cantidad_posterior, updated_at = NOW()
  WHERE id = p_inventory_item_id AND negocio_id = p_negocio_id;

    negocio_id, inventory_item_id, tipo_movimiento,
    cantidad, cantidad_anterior, cantidad_posterior,
    razon, referencia_id, referencia_tipo, usuario_id
  ) VALUES (
    p_negocio_id, p_inventory_item_id, p_tipo,
    ABS(p_cantidad), v_cantidad_anterior, v_cantidad_posterior,
    p_razon, p_referencia_id, p_referencia_tipo, p_usuario_id
  ) RETURNING id INTO v_movement_id;

  RETURN v_movement_id;
END;
$$;


ALTER FUNCTION public.registrar_movimiento_inventario(p_negocio_id uuid, p_inventory_item_id uuid, p_tipo text, p_cantidad numeric, p_razon text, p_referencia_id uuid, p_referencia_tipo text, p_usuario_id bigint) OWNER TO postgres;

